const CACHE="xylos-webdav-shell-v2",SHELL=["/app/","/app/index.html","/app/manifest.webmanifest"];self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE).then(t=>t.addAll(SHELL))),self.skipWaiting()}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(t=>Promise.all(t.filter(a=>a!==CACHE).map(a=>caches.delete(a))))),self.clients.claim()}),self.addEventListener("fetch",e=>{const t=new URL(e.request.url);t.origin!==self.location.origin||!t.pathname.startsWith("/app/")||e.respondWith(caches.match(e.request).then(a=>a||fetch(e.request).then(s=>{const n=s.clone();return caches.open(CACHE).then(c=>c.put(e.request,n)),s}).catch(()=>caches.match("/app/"))))});
